<a class="text-link small muted" href="<?= e(route_url('/admin/users')) ?>" style="margin-bottom:22px"><?= icon('arrow-left',15) ?> Back to learners</a><section class="card admin-user-hero"><span class="avatar avatar-large"><?= e(initials($learner['full_name'])) ?></span><div><h1><?= e($learner['full_name']) ?></h1><p><?= e($learner['email']) ?> · Joined <?= niceDate($learner['created_at']) ?></p><div class="page-actions"><?= badge($learner['role']) ?><?= badge($learner['status']) ?><?= badge($learner['email_verified_at']?'verified':'unverified') ?></div></div></section><div class="two-column"><div class="stack"><section class="card card-pad"><div class="card-header"><h2>Their learning journey.</h2><span class="badge badge-neutral"><?= count($enrolments) ?> enrolments</span></div><?php if($enrolments): ?><?php foreach($enrolments as $p): ?><div class="list-row"><div><h3><?= e($p['title']) ?></h3><p>Enrolled <?= niceDate($p['enrolled_at']) ?></p></div><?= badge($p['completed_at']?'completed':'in_progress') ?></div><?php endforeach; ?><?php else: ?><div class="mini-empty"><p>No enrolled paths yet. A first step is still ahead.</p></div><?php endif; ?></section><section class="card card-pad"><div class="card-header"><h2>Recorded activity.</h2><p>Latest 15 events</p></div><?php if($activity): ?><div class="mini-list"><?php foreach($activity as $a): ?><div class="mini-list-item"><span class="icon-tile orange"><?= icon(match($a['kind']){'lesson'=>'book','quiz'=>'lightbulb',default=>'briefcase'},17) ?></span><div><strong><?= e(ucfirst($a['kind'])) ?> #<?= (int)$a['reference_id'] ?></strong><small><?= niceDate($a['created_at'],'M j, Y · H:i') ?> UTC · Local activity date <?= e($a['local_date']) ?></small></div><span class="badge badge-neutral"><?= (int)$a['goal_minutes'] ?> goal credits</span></div><?php endforeach; ?></div><?php else: ?><div class="mini-empty"><p>No qualifying activity has been recorded.</p></div><?php endif; ?></section><section class="card table-card"><div class="card-pad" style="padding-bottom:0"><div class="card-header"><h2>Assessment record.</h2></div></div><div class="table-responsive"><table class="data-table"><thead><tr><th>Assessment</th><th>Status</th><th>Score</th></tr></thead><tbody><?php foreach($quizzes as $q): ?><tr><td><strong><?= e($q['title']) ?></strong><small>Quiz attempt #<?= (int)$q['id'] ?></small></td><td><?= badge($q['status']) ?></td><td><?= $q['score']!==null?round($q['score']).'%':'Awaiting score' ?></td></tr><?php endforeach; ?><?php foreach($submissions as $s): ?><tr><td><strong><a href="<?= e(route_url('/admin/reviews/' . ((int)$s['id']))) ?>"><?= e($s['title']) ?></a></strong><small>Assignment submission #<?= (int)$s['id'] ?></small></td><td><?= badge($s['status']) ?></td><td><?= $s['score']!==null?e($s['score']):'Not graded' ?></td></tr><?php endforeach; ?></tbody></table></div><?php if(!$quizzes&&!$submissions): ?><div class="mini-empty"><p>No quiz attempts or submitted assignments yet.</p></div><?php endif; ?></section><?php if($certificates): ?><section class="card card-pad"><div class="card-header"><h2>Earned certificates.</h2></div><?php foreach($certificates as $c): ?><a class="list-row" href="<?= e(route_url('/verify/' . ($c['identifier']))) ?>"><div><h3><?= e($c['path_title']) ?></h3><p><?= niceDate($c['issued_at']) ?></p></div><?= badge($c['revoked_at']?'revoked':'valid') ?></a><?php endforeach; ?></section><?php endif; ?></div><aside class="stack"><section class="card form-card"><h2 class="form-section-title">Account & access.</h2><p class="form-section-description">Role changes and suspensions revoke active sign-in sessions. Every change is audited.</p><form action="<?= e(route_url('/api/admin/users/' . ((int)$learner['id']))) ?>" method="post" data-api data-confirm="Update this learner’s current role and account status? Privileged changes are recorded and can close their active sessions."><?= csrfField() ?><div class="field"><label for="role-id">Role</label><select id="role-id" name="role_id"><?php foreach($roles as $r): ?><option value="<?= (int)$r['id'] ?>" <?= $r['id']===$learner['role_id']?'selected':'' ?>><?= e(ucfirst($r['name'])) ?></option><?php endforeach; ?></select></div><div class="field"><label for="status">Account status</label><select id="status" name="status"><option value="active" <?= $learner['status']==='active'?'selected':'' ?>>Active</option><option value="suspended" <?= $learner['status']==='suspended'?'selected':'' ?>>Suspended</option></select></div><button class="btn btn-primary btn-block">Save account access <?= icon('shield',16) ?></button></form><div class="key-value" style="margin-top:20px"><span>Timezone</span><strong><?= e($learner['timezone']) ?></strong></div><p class="fine-print" style="margin-top:13px">Passwords, authentication tokens and private lesson notes are not exposed in this interface.</p></section><section class="card form-card"><h2 class="form-section-title">A considered exception.</h2><p class="form-section-description">Manually grant access to a stage in an enrolled path. This does not grant completion, XP or a certificate.</p><form action="<?= e(route_url('/api/admin/users/' . ((int)$learner['id']) . '/override')) ?>" method="post" data-api data-confirm="Grant stage access as an audited exception? The learner must still complete the activities."><?= csrfField() ?><div class="field"><label for="stage-id">Stage</label><select id="stage-id" name="stage_id" required><option value="">Choose a stage</option><?php foreach($stages as $s): ?><option value="<?= (int)$s['id'] ?>"><?= e($s['label']) ?></option><?php endforeach; ?></select></div><div class="field"><label for="override-reason">Why is this appropriate?</label><textarea id="override-reason" name="reason" required minlength="10" maxlength="500" placeholder="Document the reason for this exception…"></textarea></div><button class="btn btn-secondary btn-block">Grant stage access <?= icon('lock',15) ?></button></form></section></aside></div>
